'use strict';
function annualEvidence(p){
 const f=p.funding,checks=p.verification?.checks||[],lookup=label=>checks.find(x=>x.label===label),rows=[];
 const add=(label,rule,actual,passed)=>rows.push([label,rule,actual,passed==null?'未取得检查结果':passed?'通过':'未通过']);
 const net=f.net_proceeds;
 add('净融资额范围','扣费后净资金 ≥ 0，且不超过本次净需求',`${money(net)}；需求上限 ${money(f.gap)}`,Number.isFinite(net)&&net>=-.2&&net<=f.gap+.2);
 for(const c of p.composition){
  const check=lookup(c.name+'用途与资产池');
  if(c.id==='leasing'){add('不启用设备租赁','本次仅生产经营周转，设备租赁本金必须为0',money(c.amount),check?.passed&&c.amount<=.01);continue;}
  const minimum=Math.min(c.capacity,10000),valid=Number.isFinite(c.amount)&&c.amount>=-.01&&(c.amount<=.01||c.amount>=minimum-.2);
  add(c.name+'金额与启用',`未启用本金为0；启用后本金至少${money(minimum)}，不超过${money(c.capacity)}。${c.basis}`,`本次本金 ${money(c.amount)}`,check==null?null:check.passed&&valid);
 }
 const leverage=lookup('杠杆边界');
 add('负债规模上限','融资后总负债 ≤ 总资产 × 设定负债率上限',leverage?`${money(leverage.actual)} ≤ ${money(leverage.limit)}`:'未取得数值',leverage?.passed);
 const operating=lookup('一年经营用款上限');
 add('生产经营用款上限','净融资额 ≤ 预计全年营业成本代理上限',operating?`${money(operating.actual)} ≤ ${money(operating.limit)}`:'未取得数值',operating?.passed);
 const cash=lookup('全期限滚动本息安全线');
 add('全年本息偿付','压力预计可用于偿债的现金 − 安全系数 × 新旧债务全年本息 ≥ 0',cash?`偿付安全余量 ${money(-cash.actual)}`:'未取得数值',cash?.passed);
 const timing=lookup('年内现金留存');
 const timingCheck=timing||lookup('年内支付时点敏感性');
 add('年内现金留存','每个检验时点：期初现金＋累计压力现金−累计本息−留存线 ≥ 0',timingCheck?`全年最小留存余量 ${money(timingCheck.actual)}`:'未取得数值',timingCheck?.passed);
 const displayed=new Set(['杠杆边界','一年经营用款上限','全期限滚动本息安全线','年内支付时点敏感性',...p.composition.map(c=>c.name+'用途与资产池')]);
 const failed=rows.filter(x=>x[3]==='未通过');
 return `<section class="card"><h2>约束检查</h2><p>${failed.length?`本次${failed.map(x=>e(x[0])).join('、')}未通过，不能将当前结果作为可采用的融资方案。`:'以下逐项核对本次金额是否满足建模约束；金额与现金检查采用独立复算结果。'}</p>${marketTable(['模型约束','判定规则','本次检验值','检查结果'],rows)}<p>负的余量表示缺口。净需求是求解覆盖目标，部分覆盖也可能满足约束；当前尚未覆盖${money(f.unfunded_gap)}。现金按年度均匀分配检查支付时点，不是逐月预测。</p><details><summary>计算目标与其他复核</summary><p>先最大覆盖净需求，再在相同覆盖水平下最小化一年成本＋${number(p.algorithm.risk_weight,2)}×情景CVaR${number(p.algorithm.cvar_alpha*100,0)}%。CVaR是目标函数中的风险项，不是“通过／未通过”的融资门槛。</p>${marketTable(['其他复核项','结果'],checks.filter(x=>!displayed.has(x.label)).map(x=>[x.label,x.passed?'通过':'未通过']))}<p>求解器${e(p.algorithm.solver)}；最优间隙${e(p.algorithm.optimality_gap??'未取得最优解')}。${e(p.verification?.note||'')}</p>${(p.algorithm.methods||[]).map(x=>`<p>${e(x)}</p>`).join('')}</details></section>`;
}
function annualDiagnosis(a){return `<section class="card financial-diagnosis"><h2>财务诊断</h2><div class="conclusion-grid">${a.year_diagnosis.map((x,i)=>`<article class="conclusion-card"><span class="conclusion-number">0${i+1}</span><h3>${e(x.title)}</h3><p>${e(x.text)}</p></article>`).join('')}</div><details class="analysis-details"><summary>诊断如何影响融资，以及方法依据</summary>${a.year_diagnosis.map(x=>`<p><strong>${e(x.title)}</strong>：${e(x.decision_link)}</p>`).join('')}${methodNote(a.diagnostics,['structure','shapley','working','cash'],'方法来源')}</details></section>`;}
function annualForecast(f){
 const h=f.history_prediction||{},p=h.future,v=h.validation;
 if(!p)return notice('请上传完整三年财报，生成下一年度现金预测。','amber');
 const [older,latest]=p.source_years,share=number((p.calibration_share??.5)*100,4),limit=number((p.calibration_limit??.3)*100,4);
 const step=(n,title,body)=>`<article class="forecast-step"><span class="forecast-step-number">${n}</span><div><h3>${title}</h3>${body}</div></article>`;
 return `<section class="card cash-prediction"><h2>${p.target_year}年现金流预测</h2><p>先用前两年预测第三年，检查偏差；再用最近两年预测下一年，并修正偏差。以下“经营现金”均指经营活动现金流量净额。</p><div class="forecast-steps">${step(1,'先估算下一年的经营现金',`<p class="forecast-equation">预计收入＝${latest}年营业收入 ×（1＋收入增长率）</p><p class="forecast-equation">现金转化比例＝（${older}年经营现金 ÷ ${older}年收入＋${latest}年经营现金 ÷ ${latest}年收入）÷ 2</p><p class="forecast-equation">修正前经营现金＝预计收入 × 现金转化比例</p><p>本次收入增长率为${number(p.growth*100,2)}%；默认延续最近一年收入增幅，并控制在−30%至50%之间，可在参数模板中调整。</p>`)}${step(2,'用历史预测找出偏差',v?`<p>用${v.source_years.join('、')}年数据按上面的方法预测${v.target_year}年，再与该年实际经营现金比较。</p><p class="forecast-equation">历史偏差＝历史预测经营现金 − 同年实际经营现金</p><p>这次历史预测${v.error>0?'偏高':v.error<0?'偏低':'与实际一致'}${v.error?money(Math.abs(v.error)):''}。</p>`:'<p>历史检验数据不足，本次修正额取0。</p>')}${step(3,'把历史偏差用于修正',`<p class="forecast-equation">初步修正额＝−历史偏差 × ${share}%</p><p class="forecast-equation">修正后经营现金＝修正前经营现金＋最终修正额</p><p>历史预测偏高，就向下修正；偏低，就向上修正。修正幅度上限按${limit}%计算。</p><details><summary>查看修正幅度的具体规则</summary><p class="forecast-equation">幅度上限＝max（|修正前经营现金|，|${latest}年实际经营现金|）× ${limit}%</p><p class="forecast-equation">最终修正额＝min（幅度上限，max（−幅度上限，初步修正额））</p><p>修正前经营现金≤0时，最终修正额取上述结果与0的较小值，保留负现金的审慎判断。修正比例和限幅比例均为可调整的模型假设。</p></details>`)}${step(4,'得到融资测算使用的现金',`<p class="forecast-equation">预计可用于偿债的现金＝修正后经营现金 − 估算维持性投资</p><p>估算维持性投资＝资本开支情景 × 维持性投资比例（资本开支情景＝最新年度购建长期资产支付的现金 × 资本开支倍数）。</p><p class="forecast-result">${p.target_year}年预计可用于偿债的现金：<strong>${money(f.annual_cash)}</strong></p><p>该结果进入融资方案的偿债约束，并作为压力测试的基准。</p>`)}</div>${annualForecastVisual(f)}</section>`;
}
function annualSolutions(){let out=heading('WORKING CAPITAL / 12 MONTHS','融资决策','固定生产经营周转，只给出一套一年期融资组合。');const gate=enterpriseGate();if(gate)return out+gate;const p=currentPlan(),f=p.funding,selected=p.composition.filter(c=>c.amount>.01);out+=compactSnapshot()+`${decisionConclusion(p)}`+metrics([['净融资需求',amountNumber(f.gap/1e8),'亿元','用户确认的外部净用款','document'],['扣费后可用资金',amountNumber(f.net_proceeds/1e8),'亿元','本金减一次性费用','layers'],['一年利息与费用',p.verification?.passed?amountNumber((f.total_assumed_interest+f.fees_due)/1e8):'未形成方案',p.verification?.passed?'亿元':'',p.verification?.passed?'按假设报价计算':'不能把零费用当作有效报价','chart']]);out+=(selected.length?annualFundingVisual(p):'')+`<section class="card"><h2>${p.verification?.passed?'推荐融资组合':'本次未形成可采用的融资组合'}</h2>${selected.length?marketTable(['产品与期限','融资本金','年利率假设','利息＋费用'],selected.map(c=>[`${c.name} · ${c.months}个月`,money(c.amount),valueFmt(c.rate,'%'),money(c.total_interest+c.total_fee)])):notice(p.decision_summary?.blockers?.[0]?.title||'本轮没有通过验证的可配置金额。','amber')}<p>${e(p.repayment_note)}</p>${selected.map(c=>`<p><strong>${e(c.name)}</strong>：${e(c.reason)}</p>`).join('')}<p>尚未覆盖需求${money(f.unfunded_gap)}。费用从融资中支付；实际报价与银行核定条件仍需确认。</p></section>`+financingEvidence(p);out+=productScreening(p);return out+btn('查看风险评估','risk','arrow','primary');}
function annualRisk(){let out=heading('ONE-YEAR STRESS REVIEW','风险评估','固定同一融资组合，逐项说明现金、回款、毛利和利率变化。');const gate=enterpriseGate();if(gate)return out+gate;const p=currentPlan(),risk=p.risk_evaluation,v=p.verification;out+=compactSnapshot()+aiInsightCard('risk')+`<section class="decision-lead"><h2>这一年能否承受压力？</h2><p>${e(risk.conclusion)}</p><p>${e(risk.reverse_summary)}</p></section>${annualRiskVisual(p)}${cvarMeaning(p)}<section class="card"><h2>情景设定与检验</h2><p>预计可用于偿债的现金，是预测经营净现金扣除估算维持性投资后的年度金额，用于覆盖已有及新增债务本息；不是实际还款支出，也不是账面现金余额。</p><p>安全线为${number(p.algorithm.target_dscr,2)}倍：每1元本息，需有${number(p.algorithm.target_dscr,2)}元预计可用于偿债的现金。情景通过不等于银行批准。</p><div class="annual-risk-grid">${risk.scenarios.map(s=>`<article class="conclusion-card"><h3>${e(s.label)} ${badge(s.passed?'达到安全线':'需调整',s.passed?'green':'amber')}</h3><p>${e(s.rule)}</p><p><strong>预计可用于偿债的现金${money(s.annual_cash)}</strong>；新旧本息${money(s.total_service)}；覆盖${valueFmt(s.dscr,'倍')}；距安全线缺口${money(s.gap_to_target)}。</p><details><summary>参数来源</summary><p>${e(s.parameter_origin)}</p></details></article>`).join('')}</div><p>${e(p.annual_context.note)}</p></section><section class="card"><h2>独立复算与下一步</h2><p>${e(v.status)}。${e(v.note)}</p>${risk.actions.map(x=>`<p>${e(x)}</p>`).join('')}<details><summary>查看每项验证</summary>${marketTable(['约束','结果','复算值','边界'],v.checks.map(c=>[c.label,c.passed?'通过':'未通过',number(c.actual,2),number(c.limit,2)]))}</details></section>`;return out+btn('查看分析报告','delivery','folder','primary');}
function annualDelivery(){let out=heading('ANNUAL DECISION BRIEF','分析报告','下一年度生产经营周转：结论、方案、风险与后续调整。');const gate=enterpriseGate();if(gate)return out+gate;const r=state.run,s=r.decision_report,p=currentPlan(),risk=p.risk_evaluation,weak=[...risk.scenarios].sort((a,b)=>b.gap_to_target-a.gap_to_target||(a.dscr??Infinity)-(b.dscr??Infinity))[0],cash=r.financial_analysis.forecast;out+=compactSnapshot()+`<div class="report-dialogue-layout"><div class="report-body"><section class="report-cover"><h2>${e(s.title)}</h2><p>${e(s.conclusion)}</p><p>12个月 · 生产经营周转 · 规划年度${cash.history_prediction.future.target_year}</p></section><section class="card"><h2>这次分析的三个重点</h2><p><strong>现金依据：</strong>误差校正后年度经营现金${money(cash.annual_operating)}，扣维持性投资后预计可用于偿债的现金${money(cash.annual_cash)}。</p><p><strong>融资建议：</strong>${s.decision.products.map(c=>`${e(c.name)} ${money(c.amount)}（${c.months}个月）`).join('；')||'当前不支持新增债务'}。扣费后可用${money(s.decision.net)}，未覆盖${money(s.decision.gap)}。</p><p><strong>风险重点：</strong>${e(weak.label)}下，距偿付安全线仍需现金${money(weak.gap_to_target)}。${e(risk.reverse_summary)}</p><p>${e(s.verification.status)}，本结果不代表授信获批或未来现金承诺。</p></section><section class="card"><h2>行动建议</h2>${risk.actions.map(x=>`<p>${e(x)}</p>`).join('')}<p>现金充足而历史周转缺口较小时，先核实新增用款预算，不因填写融资需求就认定必须借款。</p>${r.outputs.review_financing_request?.alternative?.verified?`<p>${e(r.outputs.review_financing_request.alternative.explanation)}；可在右侧确认采用。</p>`:''}<details><summary>方法与假设</summary>${s.assumptions.map(x=>`<p>${e(x)}</p>`).join('')}</details><div class="inline-actions">${download('docx','下载报告（Word）')}</div><p class="subtle-caption">报告直接下载为本地Word文件，可使用Word或WPS打开和编辑。</p></section></div>${publicDecisionChatHtml()}</div>`;return out;}
function conciseDiagnosis(a){
 if(a.year_diagnosis)return annualDiagnosis(a)+annualTrendVisual(a)+annualDupontVisual(a);
 const d=a.diagnostics||{},raw=state.run.raw_public||{},profit=a.findings.find(x=>x.title==='利润兑现'),bridge=d.working_bridges?.at(-1),lev=raw.total_assets?raw.total_liabilities/raw.total_assets:null;
 const attribution=d.roe_attribution,lead=attribution?.contributions?.reduce((best,x)=>!best||Math.abs(x.value)>Math.abs(best.value)?x:best,null);
 const profitText=(profit?.implication||'现有数据不足以判断利润兑现。')+(raw.revenue&&raw.net_profit!=null?` 净利率${number(raw.net_profit/raw.revenue*100,1)}%`:'')+(raw.net_profit>0?`，每1元利润对应${number(raw.operating_cash_flow/raw.net_profit,2)}元经营净现金。`:'。')+(lead?` 最近两年权益回报变化主要来自${lead.label}。`:'');
 let workingText='缺少可比较的年度资金占用数据，请核对上传的三年报表。';
 if(bridge){const driver=bridge.components.reduce((best,x)=>Math.abs(x.change)>Math.abs(best.change)?x:best);workingText=`${bridge.year}年经营性资金占用${bridge.nwc_change>=0?'增加':'减少'}${money(Math.abs(bridge.nwc_change))}，最大变化来自${state.boot.labels[driver.key]||driver.key}。${bridge.nwc_change>0?'业务周转需要更多现金，应先核实回款和库存安排。':'周转占用有所释放，但不能将账面变化全部视为已经到账的现金。'}`;}
 const cash=a.forecast.annual_cash,repayText=`${cash>0?'情景下有正向预计可用于偿债的现金，但可借金额仍须经过还款约束检验。':'情景下经营现金不足以覆盖维持性投资，应优先调整投入和融资需求。'} 年度预计可用于偿债的现金${money(cash)}${lev!=null?`，当前资产负债率${number(lev*100,1)}%` : ''}。`;
 return `<section class="card financial-diagnosis"><h2>财务诊断</h2><div class="conclusion-grid">${[['盈利质量',profitText],['资金占用',workingText],['偿债能力',repayText]].map(([title,text],i)=>`<article class="conclusion-card"><span class="conclusion-number">0${i+1}</span><h3>${e(title)}</h3><p>${e(text)}</p></article>`).join('')}</div><details class="analysis-details"><summary>查看诊断计算与理论依据</summary>${a.findings.map(x=>`<h3>${e(x.title)}</h3><p>${e(x.evidence)} ${e(x.implication)}</p>`).join('')}${a.diagnostics?deepDiagnosticView(a.diagnostics):''}</details></section>`;
}

function cashPredictionView(f){
 if(f.history_prediction?.future?.calibration_method)return annualForecast(f);
 const h=f.history_prediction,v=h?.validation,p=h?.future;let out='<section class="card cash-prediction"><h2>现金流预测与检验</h2>';
 if(v){out+=`<h3>用${v.source_years.join('、')}年预测${v.target_year}年</h3>${metrics([['预测经营净现金',amountNumber(v.annual_operating/1e8),'亿元','仅使用前两年数据','chart'],[`${v.target_year}年实际经营净现金`,amountNumber(v.actual/1e8),'亿元','用于检验，不参与预测','layers'],['预测绝对误差',v.absolute_percentage_error==null?'无法计算':number(v.absolute_percentage_error*100,1),v.absolute_percentage_error==null?'':'%','本次历史检验结果','shield']])}<p class="forecast-conclusion">预测比实际${v.error>=0?'高':'低'}${money(Math.abs(v.error))}。这次检验说明历史关系的偏差，不能视为未来准确率。</p><div class="forecast-basis"><h3>预测依据</h3><p>${v.source_years[0]}、${v.source_years[1]}年的经营现金占收入比例，平均为${number(v.cash_conversion*100,2)}%；按两年收入变化设定${number(v.growth*100,2)}%增长，得到预计收入${money(v.projected_revenue)}，两者相乘得到预测经营现金。</p><p>${e(v.formula)}。第三年实际数据未参与该计算。</p></div>`;}
 if(p){out+=`<h3>${p.target_year}年经营现金情景</h3><p>使用最近两个完整年度（${p.source_years.join('、')}年）更新测算，供融资和风险模型使用。</p>${metrics([['预计经营净现金',amountNumber(f.annual_operating/1e8),'亿元','两年现金转化比例外推','chart'],['预计可用于偿债的现金',amountNumber(f.annual_cash/1e8),'亿元','扣除维持性投资','layers']])}<div class="forecast-basis"><h3>下一年度测算依据</h3><p>预计收入${money(p.projected_revenue)} × 两年平均经营现金/收入比例${number(p.cash_conversion*100,2)}% ＝ 经营净现金${money(p.annual_operating)}。收入增长情景为${number(p.growth*100,2)}%；默认增幅限制在−30%至50%，可在需求参数中调整。</p><p>再扣除维持性投资，得到预计可用于偿债的现金。融资模型还会与利润、周转压力及用户压力情景比较，采用更保守的偿付边界。</p></div>`;}
 if(!p)out+=notice('该分析版本未包含两年预测依据，请用完整三年财报重新分析。','amber');
 out+=`<p class="forecast-limit">两年年报只支持情景测算；并购、一次性收付款和季节性可能使结果明显偏离实际。</p><details class="analysis-details"><summary>查看月度现金安排与模拟区间</summary>${forecastChart(f)}<div class="chart-key"><span class="line-key"></span>基准现金余额 <span class="band-key"></span>P10—P90模拟范围 <span class="line-key dashed"></span>现金余额为零</div><p>${e(f.basis)}</p><p>${e(f.band_note)}</p>${marketTable(['月','经营净现金','维持性投资','已有本息','期末现金'],f.months.map(x=>[x.month,money(x.operating),money(x.maintenance),money(x.existing_service),money(x.balance)]))}</details></section>`;
 return out;
}
const publicParameters={forecast_growth:['收入增长情景（%）',100,-30,50],capex_multiplier:['历史投资倍数',1,0,3],reserve_days:['经营现金留存（天）',1,0,180],maintenance_share:['维持性投资占比（%）',100,0,100],max_leverage:['负债率情景上限（%）',100,10,90],target_coverage:['偿付安全线（倍）',1,1,2],assumed_rate:['参考年利率（%）',100,0,30],cash_drop:['压力现金降幅（%）',100,20,40],rate_up:['压力加息（百分点）',100,1,5],credit_revenue_ratio:['信用贷款规模比例（%）',100,0,100],secured_advance_ratio:['固定资产融资比例（%）',100,0,100],factoring_advance_ratio:['应收融资比例（%）',100,0,100],leasing_advance_ratio:['设备融资比例（%）',100,0,100]};
function publicAssumptions(v){return `<div class="fields-row">${Object.entries(publicParameters).filter(([k])=>['assumed_rate','target_coverage','max_leverage','reserve_days','cash_drop','rate_up','forecast_growth'].includes(k)).map(([k,[label,s,lo,hi]])=>field(label,k,(v[k]??0)*s,'number',`data-scale="${s}" step="any" min="${lo}" max="${hi}" required`)).join('')}</div>`;}
function readPublicAssumptions(f){return Object.fromEntries([...f.querySelectorAll('[data-scale]')].map(x=>[x.name,Number(x.value)/Number(x.dataset.scale)]));}
function publicRequestInputs(p,m){return `<div class="fields-row">${field('外部净融资需求（亿元）','requested_amount',((p.requested_amount||100000)/1e8).toString(),'number','min="0.0000000001" max="100" step="any" required')}<label class="field"><span>固定规划范围</span><input value="12个月 · 生产经营周转" readonly><input type="hidden" name="requested_months" value="12"><input type="hidden" name="requested_purpose" value="经营周转"></label></div><p>填写扣除自行安排资金后的净用款。利息和费用另算，3亿元应填3。</p>`;}
function readPublicRequest(f){return {requested_amount:Number(f.elements.requested_amount.value)*1e8,requested_months:12,requested_purpose:'经营周转',decision_engine:'enterprise-v3',decision_scope:'working-capital-12m',optimization_strategy:'cost_only'};}

