function compactSnapshot(){const r=state.run;return `<div class="analysis-context"><span>${e(r.raw_public?.company_name||r.data.company_name)} · ${e(r.raw_public?.report_period||'')}</span><span>${e(r.id)} · ${e(r.mode)}</span>${badge(r.stale?'历史结果 · 输入已变化':'本次分析结果',r.stale?'amber':'blue')}</div>`;}
function enterpriseGate(){if(state.run&&state.run.input_profile?.decision_scope!=='working-capital-12m'&&state.boot.profile?.decision_scope==='working-capital-12m')return '<section class="card"><h2>请生成一年期周转分析</h2><p>当前为旧版历史报告。上传完整三年财报，确认融资金额后重新分析。</p>'+btn('填写需求并分析','new-task','play','primary')+'</section>';if(!state.run)return noRun();if(state.run.status==='执行中'&&!isComplete())return executionProgress();if(state.run.decision_engine!=='enterprise-v3'||!isComplete())return `<section class="card"><h2>生成新版企业分析</h2><p>当前为此前的分析快照。新版采用财务诊断、双目标规划和独立风险检验，请使用当前财报生成一次新分析。</p>${btn('填写需求并分析','new-task','play','primary')}</section>`;return '';}
function publicWorkspace(){const b=state.boot,m=b.public_model;return heading('ENTERPRISE FINANCIAL INTELLIGENCE','分析工作台','一年期生产经营周转 · 历史检验与校正 · 融资决策 · 风险检验')+`<section class="enterprise-hero"><div><span class="hero-kicker">FINBRIDGE / DECISION AGENT</span><h2>看懂财务状况，<br>再决定怎么融资。</h2><p>上传企业财报原值，说明金额、用途和期限。<br>让每一项建议都有数据、算法与验证依据。</p><a class="btn primary" href="/company" data-page="company">${icon('upload')}上传企业数据</a></div><div class="hero-process">${[['chart','财务分析','指标 → 诊断 → 现金预测'],['layers','融资决策','规则筛选 → 一年期MILP'],['shield','风险评估','情景 → 压力 → 独立验证']].map(([i,t,s])=>`<div>${icon(i)}<span><strong>${t}</strong><small>${s}</small></span></div>`).join('')}</div></section><section class="card" id="task-card"><div class="section-line"><div><h2>本次融资需求</h2><p>${e(b.data.company_name||'待载入企业')} · ${e(b.data.industry||'行业待确认')} · ${e(b.data.region||'地区待确认')}</p></div>${badge(b.source.startsWith('模拟')?'模拟数据':'已载入财报',b.source.startsWith('模拟')?'amber':'blue')}</div>${b.case_context?notice(b.case_context.description+'。融资需求为演示假设，同时检查资金需要与偿债能力。','blue'):''}${!m.available?notice('请上传完整、可核对的连续三年财报；缺失与勾稽问题请在企业与数据查看。','amber'):''}<form id="public-task-form">${publicRequestInputs(b.profile,m)}<details><summary>计算假设 · 利率、现金留存与安全余量</summary><p>这些是假设参数，财报中无需填写。结果保留计算口径。</p>${publicAssumptions(m.assumptions)}</details><label class="review-row"><input name="use_ai" type="checkbox" ${b.model_configured?'checked':'disabled'}>启用 AI 财务洞察、风险研判与工具规划（使用当前配置的模型）</label><div class="inline-actions"><button class="btn primary" type="submit">${icon('play')}开始完整分析</button><span class="subtle-caption">四个模块一次生成，可复核、可继续调整。</span></div><div id="public-task-error" role="alert"></div></form></section>`;}
