 if(b.case_context)out+=`<section class="card"><details><summary>算例来源与口径说明</summary><p>${e(b.case_context.description)}</p>${b.case_context.notes.map(n=>`<p class="subtle-caption">${e(n)}</p>`).join('')}<details><summary>年报原文与逐项取数来源</summary>${b.case_context.sources.map(s=>`<p><a href="${e(s.url)}" target="_blank" rel="noopener">${s.year}年官方年度报告</a></p>`).join('')}<p>各年度科目的原文页码随数据保留。手动修改后以当前输入为准。</p></details></details></section>`;
