 out+='</div><details><summary>公开附注（可选，披露时直接填写）</summary><div class="fields-row">';
 for(const [k,t] of Object.values(b.public_blocks).flat().filter(([k])=>!required.includes(k)))out+=`<label class="field"><span>${e(t)}</span><input data-public-field="${k}" type="number" step="any" value="${d[k]==null?'':d[k]/1e8}" placeholder="未披露可留空"></label>`;
 return out+`</div></details><p class="subtle-caption">页面金额统一为亿元。三年核心数据共同支持动态诊断、融资约束和风险验证；附注不影响基础完整性，但缺少时不计算对应补充指标。</p><button class="btn primary" type="submit">保存并填写融资需求</button><div id="public-company-error" role="alert"></div></form></section>`;
