function executionProgress(){const r=state.run,ev=r?.events||[];return `<section class="card execution-progress"><h2>${r?.status==='执行中'?'<span class="spinner"></span> 正在分析企业财报':'分析未完成'}</h2><p>依次计算、优化、研究与独立验证，已执行工具结果会保留。</p><div class="tool-progress">${state.boot.tools.map(t=>{const x=ev.find(x=>x.tool===t.id);return `<div>${icon(x?.status==='完成'?'check':'clock')}<span>${e(t.label)}</span>${badge(x?.status||'等待')}</div>`;}).join('')}</div>${ev.filter(x=>x.status==='失败').map(x=>notice(x.result?.error||'工具未完成','red')).join('')}</section>`+(r?.ai_insights?.financial?aiInsightCard('financial'):'');}
function aiInsightCard(section){
 const x=state.run?.ai_insights?.[section],title=section==='financial'?'AI 财务洞察':'AI 风险研判';
 if(!x)return `<section class="card ai-insight"><h2>${title}</h2><p>在分析工作台启用 AI 并重新分析，生成基于本企业数据的专业解读。</p></section>`;
 if(x.status==='running'||x.status==='pending')return `<section class="card ai-insight" aria-live="polite"><h2><span class="spinner"></span> ${title}</h2><p>${x.status==='pending'?'等待风险测算完成后，结合本次融资方案分析重点。':'正在结合本企业计算结果分析重点…'}</p></section>`;
 if(x.status!=='completed')return `<section class="card ai-insight"><h2>${title}</h2><p>${e(x.message||'本次解读未完成，计算结果已保留。')}</p>${btn('返回分析工作台','workspace','arrow')}</section>`;
 const paragraphs=String(x.text).split(/\n\s*\n/).filter(Boolean).map(t=>`<p>${e(t).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\n/g,'<br>')}</p>`).join('');
 return `<section class="card ai-insight"><div class="section-line"><h2>${title}</h2>${badge(x.model,'blue')}</div><div class="ai-insight-text">${paragraphs}</div><span class="subtle-caption">基于本次计算结果 · 已保存到当前分析</span></section>`;
}
function publicExecution(){
 let out=heading('FINANCIAL ANALYSIS','财务分析','五块财务诊断 → 一期现金预测与校正 → 一年期生产经营周转决策。');const gate=enterpriseGate();if(gate)return out+gate;
 const r=state.run,a=r.financial_analysis,all=r.outputs.calculate_ratios;out+=compactSnapshot();if(!a?.available)return out+aiInsightCard('financial')+notice('暂停预测与求解：'+[...(a?.missing||[]).map(k=>state.boot.labels[k]||k),...(a?.issues||[])].join('；'),'amber');
 const preferred=['current_ratio','debt_to_asset_ratio','net_profit_margin','operating_cash_flow_to_net_profit','receivables_days','cash_conversion_cycle'];
 out+=`<section class="card"><div class="section-line"><h2>财务指标</h2><span class="subtle-caption">展开查看公式与来源</span></div><div class="ratio-grid">${preferred.filter(k=>all[k]).map(k=>{const x=all[k];return `<details class="ratio-tile"><summary><span>${e(x.label)}</span><strong>${e(valueFmt(x.value,x.unit))}</strong></summary><p>${e(x.formula)}</p><small>${e(x.data_issue||'来源：'+x.sources.map(s=>state.boot.labels[s]||s).join('、'))}</small></details>`;}).join('')}</div><details><summary>全部指标与计算口径</summary>${marketTable(['指标','结果','公式','数据情况'],Object.values(all).filter(x=>x.kind!=='公开原值').map(x=>[x.label,valueFmt(x.value,x.unit),x.formula,x.data_issue||'已计算']))}</details></section>`;
 out+=conciseDiagnosis(a);
 out+=aiInsightCard('financial');
 out+=cashPredictionView(a.forecast);
 return out+btn('查看融资决策','solutions','arrow','primary');
}
function forecastChart(f){const rows=f.months,w=880,h=260,pad=45,values=rows.flatMap(x=>[x.p10,x.p90,x.balance,0]);let lo=Math.min(...values),hi=Math.max(...values);if(hi===lo)hi=lo+1;const X=i=>pad+i*(w-pad*2)/Math.max(1,rows.length-1),Y=v=>h-pad-(v-lo)/(hi-lo)*(h-pad*2),points=k=>rows.map((r,i)=>`${X(i)},${Y(r[k])}`).join(' ');return `<svg class="enterprise-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="未来现金余额情景及模拟区间"><polygon points="${points('p90')+' '+rows.map((r,i)=>`${X(i)},${Y(r.p10)}`).reverse().join(' ')}" fill="#d9e9df"/><line x1="${pad}" y1="${Y(0)}" x2="${w-pad}" y2="${Y(0)}" stroke="#b85b48" stroke-dasharray="6 5"/><polyline points="${points('balance')}" fill="none" stroke="#137864" stroke-width="3"/>${[lo,(hi+lo)/2,hi].map(v=>`<text x="4" y="${Y(v)}" fill="#7b8c83" font-size="11">${amountNumber(v/1e8,0)}</text>`).join('')}<text x="4" y="15" fill="#7b8c83" font-size="11">亿元</text><text x="${pad}" y="${h-10}" font-size="11" fill="#7b8c83">第1月</text><text x="${w-pad-42}" y="${h-10}" font-size="11" fill="#7b8c83">第${rows.length}月</text></svg>`;}
function publicSolutions(){
 if(state.run?.input_profile?.decision_scope==='working-capital-12m')return annualSolutions();
 let out=heading('FINANCING DECISION','融资决策','产品规则先筛选，再平衡融资成本与现金流风险；金额由 Python 求解。');const gate=enterpriseGate();if(gate)return out+gate;
 const p=currentPlan(),f=p.funding,d=p.decision_summary||{};out+=compactSnapshot()+`<section class="decision-lead">${badge(p.verification?.passed?'通过数学验证':'需要调整',p.verification?.passed?'':'amber')}<h2>${e(d.title||p.status)}</h2><p>${e(d.text||p.status)}</p></section>`;
 out+=metrics([['外部净用款需求',amountNumber(f.gap/1e8),'亿元','用户确认的需求','document'],['组合融资本金',amountNumber(f.debt_total/1e8),'亿元','含支付费用的部分','chart'],['扣费后可用资金',amountNumber((f.net_proceeds||0)/1e8),'亿元','本金减一次性费用','layers'],['尚未覆盖需求',amountNumber(f.unfunded_gap/1e8),'亿元','需缩减、分期或补充资金','warning']]);
 const selected=p.composition.filter(c=>c.amount>.01);out+=`<section class="card"><h2>推荐融资组合</h2>${selected.length?marketTable(['融资产品','本金','假设年利率','期限','还款方式','全期利息','费用'],selected.map(c=>[c.name,money(c.amount),valueFmt(c.rate,'%'),c.months+'个月',c.repayment,money(c.total_interest),money(c.total_fee)])):notice('当前约束下新增本金为零。请查看限制原因；零表示没有找到支持新增借款的空间。','amber')}<p>${e(f.note||'')}</p>${selected.map(c=>`<div class="product-reason"><strong>${e(c.name)}</strong><p>${e(c.reason)}</p><small>申请前确认：${e(c.conditions.join('；'))}</small></div>`).join('')}</section>`;
 if(!selected.length)out+=`<section class="card"><h2>为什么没有配置融资</h2>${(p.verification?.checks||[]).filter(c=>!c.passed).map(x=>`<p>${e(x.label)}：超出模型边界${e(money(Math.max(0,(x.actual||0)-(x.limit||0))))}。</p>`).join('')}${p.composition.filter(x=>!x.enabled).map(c=>`<p>${e(c.name)}：${e(c.exclusion_reason)}。</p>`).join('')}<p>可在报告右侧调整融资需求、期限或情景假设，确认后重新分析。</p></section>`;
 out+=financingEvidence(p);out+=`<section class="card"><div class="section-line"><h2>成本与风险的权衡</h2>${badge('三组实际求解','blue')}</div>${marketTable(['策略','融资本金','净资金','全期利息＋费用','95%尾部现金缺口'],(p.frontier||[]).map(s=>[s.title,money(s.amount),money(s.net),money(s.cost),money(s.cvar)]))}<p>CVaR（条件风险价值）是最差5%模拟路径的平均现金缺口。这里的缺口指低于经营现金留存线的金额，越低表示尾部压力越小。</p><p class="subtle-caption">${e(p.frontier_note||'')}。当前推荐${e(p.strategy||'均衡方案')}，备选互为替代，不能叠加申请。</p></section><section class="card"><h2>产品筛选与融资边界</h2>${marketTable(['产品','本次状态','模型上限','筛选依据'],p.composition.map(c=>[c.name,c.status,money(c.capacity),c.exclusion_reason||c.basis]))}<details><summary>算法与情景参数</summary><p>混合整数线性规划（MILP）：整数变量决定启用产品，连续变量决定金额。先最大覆盖净需求，再最小化全期成本与加权CVaR；比较权重0、0.5、2。</p><p>95% CVaR使用${e(p.algorithm.samples)}条固定种子情景；成本与风险均以金额计量。逐个滚动窗口检查还款，不假定短期贷款自动续期。</p>${p.algorithm.assumptions.map(x=>`<p>${e(x)}</p>`).join('')}<p>求解器：${e(p.algorithm.solver)}；最优间隙：${e(p.algorithm.optimality_gap??'未取得最优解')}。</p></details></section>`;
 const alt=state.run.outputs.review_financing_request?.alternative;if(alt?.verified)out+=`<section class="card"><h2>需求复审：建议分阶段安排</h2><p>${e(alt.explanation)}</p><p>当前需求尚未修改。在报告对话中选择“采用调整建议”，确认后才更新。</p></section>`;
 return out+`<div class="inline-actions">${btn('查看风险与压力测试','risk','shield','primary')}${btn('报告与交互调整','delivery','mail')}</div>`;
}
function publicRisk(){
 if(state.run?.input_profile?.decision_scope==='working-capital-12m')return annualRisk();
 let out=heading('RISK ASSESSMENT','风险评估','查看压力情景、尾部损失与临界条件，复核方案是否满足计算约束。');const gate=enterpriseGate();if(gate)return out+gate;
 const p=currentPlan(),risk=state.run.outputs.assess_risk.enterprise_risk,v=state.run.outputs.verify_decision;out+=compactSnapshot()+aiInsightCard('risk');if(!risk?.available)return out+notice('财报或求解未完成，暂停风险评估。','amber');
 out+=`<section class="card"><h2>风险结论</h2><p>${e(risk.conclusion)}</p><p>${e(risk.reverse_summary)}</p></section>`+metrics([['现金余额小于零',number(risk.cash_shortfall_probability*100,2),'%','情景频率，非真实违约率','warning'],['跌破现金留存线',number(risk.reserve_breach_probability*100,2),'%','早于现金耗尽的预警','shield'],['95%尾部现金缺口',amountNumber(risk.cvar/1e8),'亿元','最差5%路径的平均储备缺口','chart']]);
 out+=riskEvidence(risk);out+=`<section class="card"><h2>组合压力测试</h2><p>固定融资组合，比较同一滚动12个月现金与本息。本次约束采用预计可用于偿债的现金下降${number(p.algorithm.planning_stress.cash_drop*100,1)}%、利率上升${number(p.algorithm.planning_stress.rate_up*100,2)}个百分点；现金降幅已综合企业诊断与用户压力，取更严格者。</p>${stressChart(p)}<div class="chart-key"><span class="line-key dashed"></span>安全线 ${number(p.algorithm.target_dscr,2)}倍 <span class="dot-key green"></span>达到安全线 <span class="dot-key amber"></span>够还但余量不足 <span class="dot-key red"></span>现金不足</div><p class="subtle-caption">柱高为偿债覆盖倍数（DSCR）。1倍表示刚好够还；安全线为本次模型假设，非银行统一审批标准。预计可用于偿债的现金（CFADS）使用报表代理口径。</p>${marketTable(['情景','预计可用于偿债的现金','新增本息','已有本息','覆盖倍数','达到安全线还需现金'],p.scenarios.map(s=>[s.label,money(s.cfads),money(s.new_annual_service),money(s.existing_annual_service),valueFmt(s.dscr,'倍'),money(s.gap_to_target)]))}</section><section class="card"><h2>蒙特卡洛：最薄弱时点的现金分布</h2>${histogramChart(risk.histogram)}<p class="subtle-caption">每根柱子是一段“全期限最低现金余额”区间，柱高是该区间的模拟次数；负余额标红。共${risk.samples}条独立路径，未重复使用优化样本。</p><details><summary>模拟假设与逆向测试方法</summary>${risk.assumptions.map(s=>`<p>${e(s)}</p>`).join('')}<p>逆向测试固定其他条件，降低现金或用二分搜索提高利率，查找触及偿付安全线的临界点，不是市场预测。</p></details></section><section class="card"><div class="section-line"><h2>独立方案验证</h2>${badge(v.status,v.passed?'':'amber')}</div>${marketTable(['检查项','结果','复算值','边界'],v.checks.map(c=>[c.label,c.passed?'通过':'未通过',number(c.actual,2),number(c.limit,2)]))}<p class="subtle-caption">${e(v.note)}</p><div class="action-list">${risk.actions.map((x,i)=>`<div><span>${i+1}</span><p>${e(x)}</p></div>`).join('')}</div></section>`;
 return out+btn('查看分析报告','delivery','folder','primary');
}
function stressChart(p){const w=880,h=240,pad=40,rows=p.scenarios,target=p.algorithm.target_dscr,vs=rows.map(s=>s.dscr).filter(v=>v!=null),lo=Math.min(0,...vs),hi=Math.max(target*1.3,...vs,1),Y=v=>h-pad-(v-lo)/(hi-lo)*(h-pad*2),step=(w-2*pad)/rows.length;return `<svg class="enterprise-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="情景偿债覆盖倍数"><line x1="${pad}" x2="${w-pad}" y1="${Y(0)}" y2="${Y(0)}" stroke="#d8e0d9"/>${rows.map((s,i)=>{const v=s.dscr,col=v==null?'#aab5ad':v>=target-1e-8?'#137864':v>=1?'#c69d4c':'#b75b48',x=pad+i*step+step*.15;return `<rect x="${x}" y="${v==null?Y(0):Math.min(Y(v),Y(0))}" width="${step*.7}" height="${v==null?0:Math.abs(Y(v)-Y(0))}" fill="${col}" rx="3"/><text x="${x+step*.35}" y="${v==null?Y(0)-8:Y(v)-8}" text-anchor="middle" font-size="12" fill="#355146">${v==null?'无本息':number(v,2)}</text><text x="${x+step*.35}" y="${h-12}" text-anchor="middle" font-size="11" fill="#73877a">${e(s.label)}</text>`;}).join('')}<line x1="${pad}" x2="${w-pad}" y1="${Y(target)}" y2="${Y(target)}" stroke="#b75b48" stroke-dasharray="6 5"/></svg>`;}
function histogramChart(d){const w=880,h=240,pad=42,max=Math.max(1,...d.counts),step=(w-pad*2)/d.counts.length;return `<svg class="enterprise-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="模拟最低现金余额频数分布">${d.counts.map((n,i)=>{const height=n/max*(h-pad*2);return `<rect x="${pad+i*step}" y="${h-pad-height}" width="${step-3}" height="${height}" fill="${d.edges[i]<0?'#b75b48':'#458878'}"><title>${number(d.edges[i])}—${number(d.edges[i+1])}亿元：${n}条路径</title></rect>`;}).join('')}<text x="${pad}" y="20" font-size="11" fill="#73877a">模拟次数 · 最高${max}</text><text x="${pad}" y="${h-14}" font-size="11" fill="#73877a">${number(d.edges[0])}亿元</text><text x="${w-pad-90}" y="${h-14}" font-size="11" fill="#73877a">${number(d.edges.at(-1))}亿元</text></svg>`;}
function publicDelivery(){
 if(state.run?.input_profile?.decision_scope==='working-capital-12m')return annualDelivery();
 let out=heading('DECISION REPORT','分析报告','汇总财务发现、融资策略与风险边界。右侧可追问或提出修改。');const gate=enterpriseGate();if(gate)return out+gate;
 const r=state.run,s=r.decision_report,p=currentPlan(),ctx=r.outputs.analyze_industry_region;
 out+=compactSnapshot()+`<div class="report-dialogue-layout"><div class="report-body"><section class="report-cover"><div class="eyebrow">FINBRIDGE / ${e(r.id)}</div><h2>${e(s.title)}</h2><p>${e(s.conclusion)}</p><div class="report-stats"><div><span>可用于本次需求</span><strong>${e(money(s.decision.net))}</strong></div><div><span>尚需调整支出</span><strong>${e(money(s.decision.gap))}</strong></div><div><span>全期利息＋费用</span><strong>${e(money(s.decision.interest+s.decision.fees))}</strong></div></div></section><section class="card"><h2><span class="section-number">01</span>财务判断</h2>${s.financial_takeaways.map(x=>`<article class="report-finding"><h3>${e(x.title)}</h3><p>${e(x.finding)}</p><small>${e(x.implication)}</small></article>`).join('')}<a href="/analysis" data-page="execution" class="text-link">完整指标、诊断与预测 →</a></section><section class="card"><h2><span class="section-number">02</span>融资策略</h2>${s.decision.products.length?`<ul class="report-products">${s.decision.products.map(x=>`<li><strong>${e(x.name)}</strong><span>${e(money(x.amount))} / ${x.months}个月</span></li>`).join('')}</ul>`:`<p>${e(p.decision_summary?.blockers?.[0]?.action||'当前没有通过验证的融资组合，请先核对限制原因。')}</p>`}<p>${e(p.decision_summary?.rationale?.[0]||'额度同时受用途、资产池、杠杆和现金约束。')}</p><a href="/solutions" data-page="solutions" class="text-link">产品筛选、费用与权衡 →</a></section><section class="card"><h2><span class="section-number">03</span>风险与可执行条件</h2><p>${e(s.risk.reverse||'暂缺有效风险结果')}</p><p>独立验证：<strong>${e(s.verification.status)}</strong>。${e(s.verification.note)}</p><p>尾部现金缺口 ${e(money(s.risk.cvar))}；属于敏感性结果，实际还款节奏以合同复核。</p><a href="/risk" data-page="risk" class="text-link">压力情景与验证记录 →</a></section><section class="card"><h2><span class="section-number">04</span>下一步</h2><div class="action-list">${s.actions.map((x,i)=>`<div><span>${i+1}</span><p>${e(x)}</p></div>`).join('')}</div>${r.outputs.review_financing_request?.alternative?.verified?`<div class="notice amber">${e(r.outputs.review_financing_request.alternative.explanation)}<br>在右侧输入“采用调整建议”，确认后更新。</div>`:''}<details><summary>市场依据、假设与工具记录</summary><p>${e(ctx?.status||ctx?.source_status||'未取得近期资料')}</p><p>${e(ctx?.summary||'财务计算不等于实时市场资料。')}</p>${(ctx?.sources||[]).slice(0,6).map(x=>`<p>${safeSourceLink(x)} · ${e(x.published_at||'日期未核验')}</p>`).join('')}${s.assumptions.map(x=>`<p>${e(x)}</p>`).join('')}<ul>${r.events.map(x=>`<li>${e(x.label)} · ${e(x.status)}</li>`).join('')}</ul></details><div class="inline-actions">${download('docx','下载报告（Word）')}</div><p class="subtle-caption">报告直接下载为本地Word文件，可使用Word或WPS打开和编辑。</p></section></div>${publicDecisionChatHtml()}</div>`;return out;
}
function safeSourceLink(x){return /^https?:\/\//i.test(x.url||'')?`<a href="${e(x.url)}" target="_blank" rel="noopener noreferrer">${e(x.title||x.id)}</a>`:e(x.title||x.id||'');}
function chatModelLabel(){const d=state.models||{list:[],platform:[]};const self=(d.list||[]).find(m=>m.isSelected);const plat=(d.platform||[]).find(p=>p.isSelected);return self?e(self.displayName||self.modelId):plat?`平台托管 · ${e(plat.name)}`:'默认模型';}
function chatModelPopover(){const d=state.models||{list:[],platform:[]};const row=(m,kind)=>`<div class="chat-model-item"><div class="chat-model-name"><strong>${e(kind==='platform'?m.name:(m.displayName||m.modelId))}</strong><small>${e(kind==='platform'?'平台托管 · 管理员配置':m.modelId)}</small></div>${m.isSelected?badge('使用中','green'):`<button type="button" class="btn ghost small" data-action="${kind==='platform'?'platform-use':'model-use'}" data-model="${m.id}">使用</button>`}</div>`;const items=[...(d.platform||[]).map(m=>row(m,'platform')),...(d.list||[]).map(m=>row(m,'self'))];return `<div class="chat-model-pop" role="menu" aria-label="选择对话模型">${items.length?items:'<p class="subtle-caption">暂无可用模型；未选择时依次使用平台托管与环境变量模型。</p>'}<div class="chat-model-foot"><button type="button" class="btn ghost small" data-action="chat-model-manage">${icon('plus')}添加或管理模型</button></div></div>`;}
function publicDecisionChatHtml(){const chat=state.decisionChatFor===state.run.id?state.decisionChat:null,busy=!!state.decisionChatBusy,configured=state.boot.model_configured,msg=chat?.messages||[],old=chat?.head_run_id&&chat.head_run_id!==state.run.id,pending=msg.at(-1)?.pending_update;return `<section class="card decision-dialogue ${state.dialogueExpanded?'expanded':''}" id="decision-chat" aria-label="企业财务与融资交互"><div class="section-line"><h2>${icon('mail')}决策对话</h2><button type="button" class="btn small" id="expand-dialogue" aria-expanded="${!!state.dialogueExpanded}">${state.dialogueExpanded?'收起对话':'展开对话'}</button></div><p class="subtle-caption">AI 助手已获得当前企业数据与分析。可直接提问；精确调整请展开参数模板，填写后发送，生成临时方案。</p>${old?`<button class="btn" data-chat-head="${e(chat.head_run_id)}">载入最新版本</button>`:''}<div class="decision-dialogue-log" id="sme-chat-log" aria-live="polite">${msg.length?msg.map(publicChatMessageHtml).join(''):'<div class="dialogue-welcome"><strong>围绕这家企业继续分析</strong><p>为什么推荐这个组合？回款下降后能否偿还？需求改成0.006亿元会怎样？</p></div>'}${busy?`<article class="dialogue-message user"><p>${e(state.decisionChatDraft)}</p></article><p><span class="spinner"></span> 正在调用分析工具…</p>`:''}</div>${pending&&!old?proposalHtml(pending,busy):''}${parameterTemplateHtml(busy||!configured||old)}<div class="dialogue-prompts">${[['解释推荐依据','为什么推荐这个组合？'],['测算融资上限','保持12个月和生产经营周转用途，测算最大可融资额'],['调整融资金额','把一年期生产经营周转融资需求改成0.006亿元']].map(([t,q])=>`<button class="btn small" data-finance-question="${e(q)}" ${busy||!configured||old?'disabled':''}>${t}</button>`).join('')}</div><form id="decision-chat-form"><div class="chat-model-line"><label for="finance-chat-input">继续分析或提出修改</label><span class="chat-model-slot"><button type="button" class="btn ghost small" data-action="chat-model" aria-haspopup="menu" aria-expanded="${!!state.chatModelOpen}" title="选择本轮对话使用的模型" ${busy||old?'disabled':''}>${icon('bolt')}${chatModelLabel()}${icon('chevron')}</button>${state.chatModelOpen?chatModelPopover():''}</span></div><textarea id="finance-chat-input" name="message" rows="3" maxlength="2000" placeholder="可直接询问分析问题；调整多个参数时，从上方折叠区复制模板填写。" required ${busy||!configured||old?'disabled':''}>${e(state.decisionChatDraft||'')}</textarea><button type="submit" class="btn primary wide" ${busy||!configured||old?'disabled':''}>${busy?'正在处理…':'发送'}</button></form><p id="decision-chat-error" role="alert">${e(state.decisionChatError||'')}</p>${!configured?'<small>尚未配置API，现有结果仍可查看。</small>':''}</section>`;}
function proposalHtml(p,busy){return `<div class="update-proposal" id="decision-update-proposal" role="region" aria-labelledby="decision-update-title" data-proposal-id="${e(p.id)}"><strong id="decision-update-title">是否更新并重新分析？</strong><p class="proposal-summary">${p.items.length?`请核对以下 ${p.items.length} 项修改，确认后才会重新分析。`:'更新分析重点并重新运行模型。'}</p><div class="proposal-changes" role="region" aria-label="本次参数变更对照">${marketTable(['项目','当前','拟修改为'],p.items.map(x=>[publicParameters[x.key]?.[0]||x.label,typeof x.before==='number'?valueFmt(x.before,x.unit):x.before??'未设置',typeof x.after==='number'?valueFmt(x.after,x.unit):x.after]))}</div><p>保存新版本，旧报告保留。</p><div class="inline-actions proposal-actions"><button type="button" class="btn primary" data-confirm-proposal="${e(p.id)}" data-confirmed="true" ${busy?'disabled':''}>是，更新并重新分析</button><button type="button" class="btn" data-confirm-proposal="${e(p.id)}" data-confirmed="false" ${busy?'disabled':''}>否，保留当前结果</button></div></div>`;}
function publicChatMessageHtml(m){let out=`<article class="dialogue-message ${m.role}"><strong>${m.role==='user'?'您':'融智'}</strong><p>${e(m.content)}</p>`;if(m.follow_up)out+=`<p>${e(m.follow_up)}</p>`;if(m.card&&!m.pending_update)out+=`<details><summary>计算依据与本轮工具</summary><p>融资本金 ${e(m.card.proposed)} · 剩余需求 ${e(m.card.gap)}</p>${(m.card.metrics||[]).map(x=>`<p><strong>${e(x.label)}：${e(x.display)}</strong><br>${e(x.formula)}</p>`).join('')}${(m.tools||[]).map(x=>`<p>${e(x.label)} · ${e(x.status)}</p>`).join('')}${(m.source_references||[]).map(x=>`<p>${safeSourceLink(x)}</p>`).join('')}</details>`;return out+scenarioCards(m)+'</article>';}
function scrollConversation(){const el=document.querySelector('#sme-chat-log');if(el)el.scrollTop=el.scrollHeight;requestAnimationFrame(()=>document.querySelector('#decision-update-proposal .proposal-actions')?.scrollIntoView({block:'nearest',inline:'nearest'}));}
async function loadDecisionChat(){if(!isComplete()||!state.run.public_analysis||state.page!=='delivery'||state.decisionChatFor===state.run.id||state.decisionChatLoading)return;const id=state.run.id;state.decisionChatLoading=true;try{const chat=await api(`/api/runs/${id}/conversation`);if(state.run.id===id){state.decisionChat=chat;state.decisionChatFor=id;state.decisionChatError='';render();scrollConversation();}}catch(err){state.decisionChatError=err.message;const el=document.querySelector('#decision-chat-error');if(el)el.textContent=err.message;}finally{state.decisionChatLoading=false;}}
async function updateConversation(r){state.decisionChat=r;state.decisionChatFor=r.head_run_id;state.decisionChatDraft='';if(r.saved_version){await refreshBoot();await loadRun(r.head_run_id);}state.decisionChatError='';}
async function sendDecisionMessage(message){if(!message.trim()||state.decisionChatBusy)return;const id=state.run.id;state.decisionChatBusy=true;state.decisionChatDraft=message;state.decisionChatError='';render();try{const r=await api(`/api/runs/${id}/conversation`,{method:'POST',body:{message}});if(state.run.id===id)await updateConversation(r);else toast('原分析的对话已完成，可返回查看。');}catch(err){state.decisionChatError=err.message;}finally{state.decisionChatBusy=false;render();scrollConversation();}}
async function confirmDecisionProposal(id,confirmed){if(state.decisionChatBusy)return;state.decisionChatBusy=true;state.decisionChatError='';render();try{const r=await api(`/api/runs/${state.run.id}/conversation/confirm`,{method:'POST',body:{proposal_id:id,confirmed}});await updateConversation(r);toast(confirmed?'四个模块已重新分析并更新。':'已保留当前结果。');}catch(err){state.decisionChatError=err.message;}finally{state.decisionChatBusy=false;render();scrollConversation();}}
function publicKnowledge(){return publicWorkspace();}
function methodNote(d,ids,title){if(!d?.methods)return '';return `<details class="method-note"><summary>${e(title)}</summary>${ids.filter(k=>d.methods[k]).map(k=>{const m=d.methods[k];return `<p><a href="${e(m.url)}" target="_blank" rel="noopener">${e(m.basis)}</a>：${e(m.application)}</p>`;}).join('')}<small>论文或理论支持分析方法；具体融资比例、利率与安全线为本次规则假设。</small></details>`;}
function diagnosticInsights(d,module){return (d.insights||[]).filter(x=>x.module===module).map(x=>`<article class="diagnostic-insight"><strong>${e(x.title)}</strong><p>${e(x.text)}</p><small>${e(x.action)}</small></article>`).join('');}
function diagnosticScenarioTable(d){const cases=d.support?.scenarios;if(!cases)return '';return `<h3>这些变化会减少多少现金？</h3><p>保持融资需求不变，分别改变现金转化、利润率和周转速度。参数来自本企业历史，组合压力不表示一定会同时发生。</p>${marketTable(['企业情景','年度经营净现金','较基准变化','新增资金占用','毛利率下降的现金影响'],cases.map(x=>[x.label,money(x.ocf),money(x.cash_change),money(x.nwc_increase),money(x.gross_margin_cash_loss)]))}<p class="diagnosis-evidence">约束最紧的诊断情景：${e(d.support.binding_scenario)}。后续融资模型还会与用户设置的现金压力比较，采用更低的预计可用于偿债的现金。</p><details><summary>查看本企业的情景参数</summary>${marketTable(['情景','应收天数','存货天数','应付天数','毛利率','情景收入'],cases.map(x=>[x.label,number(x.drivers.dso,1),number(x.drivers.dio,1),number(x.drivers.dpo,1),number(x.drivers.gross_margin*100,2)+'%',money(x.projected_revenue)]))}</details>`;}
function improvementTable(d){if(!d.improvements?.length)return '';return `<details><summary>改善资金占用的量化参考</summary>${marketTable(['改善动作','假设提前天数','占用减少代理'],d.improvements.map(x=>[x.label,number(x.days,1),money(x.cash_release_proxy)]))}<p>提前天数仅是可调整的敏感性示例，不是论文规定的最优账期。改善尚未落实，不计入融资资金来源。</p></details>`;}
function financingEvidence(p){if(p.annual_context)return annualEvidence(p);if(!p.algorithm?.constraints?.length)return '';return `<section class="card"><h2>这次方案受哪些财务条件限制？</h2>${marketTable(['约束','本次边界或现金值','来源'],p.algorithm.constraints.map(x=>[x.label,x.value==null?'旧数据未形成该情景':money(x.value),x.sources.map(k=>state.boot.labels[k]||({financial_history:'连续年度诊断',requested_amount:'本次净融资需求',max_leverage:'用户负债率上限',cash_drop:'用户现金压力',maintenance_share:'维持性投资假设'}[k]||k)).join('、')]))}<p>诊断参考：${e(p.algorithm.diagnosis_basis)}。固定资产池用于抵押与设备租赁，剔除重复占用；应收池单独用于保理。额度仍须同时通过现金偿付约束。</p><details><summary>建模依据与参数性质</summary>${(p.algorithm.methods||[]).map(x=>`<p>${e(x)}</p>`).join('')}<p>产品融资比例、报价、风险权重和偿付安全线属于假设，可在任务参数或对话中试算。研究依据不等于机构授信，账面固定资产和应收也不等于合格担保物。</p></details></section>`;}
function riskEvidence(r){let out='';if(r.dimensions?.length)out+=`<section class="card"><h2>本次风险评估覆盖什么？</h2><div class="diagnosis-grid">${r.dimensions.map(x=>`<article class="diagnosis"><h3>${e(x.title)}</h3><p>${e(x.finding)}</p><small>${e(x.action)}</small></article>`).join('')}</div></section>`;if(r.diagnostic_stress?.length)out+=`<section class="card"><h2>财务诊断情景下，当前方案还能否偿付？</h2><p>固定本次组合不变，把前面的利润率和周转压力带入；避免重新选方案后掩盖原方案的弱点。</p>${marketTable(['企业情景','年度预计可用于偿债的现金','覆盖倍数','达到安全线还缺现金','结果'],r.diagnostic_stress.map(x=>[x.label,money(x.annual_cash),valueFmt(x.dscr,'倍'),money(x.gap_to_target),x.passed?'达到安全线':'需调整']))}</section>`;if(r.sample_stability)out+=`<section class="card"><details><summary>模拟稳定性、理论依据与可信边界</summary>${marketTable(['样本数','现金不足频率','储备不足频率','尾部现金缺口'],r.sample_stability.map(x=>[x.samples,number(x.cash_frequency*100,2)+'%',number(x.reserve_frequency*100,2)+'%',money(x.cvar)]))}<p>给定模拟模型的现金不足频率抽样范围：${number(r.frequency_sampling_range.lower*100,2)}%—${number(r.frequency_sampling_range.upper*100,2)}%。${e(r.sampling_note)}</p><p>${e(r.theory)}</p><p>数学复算和不同种子的模拟可以检查实现及情景稳定性；没有真实合同、季节性和样本外验证，不能宣称风险预测准确或方案一定获批。</p></details></section>`;return out;}
function historyEditor(d,b){const years=d.financial_history.slice(0,-1);if(!years.length)return '<p>当前仅一期；上传连续三年财报可增强动态分析。</p>';return `<div class="history-scroll"><table><thead><tr><th>财报科目</th>${years.map(r=>`<th>${r.year}年度</th>`).join('')}</tr></thead><tbody>${Object.values(b.public_blocks).flat().map(([k,t])=>`<tr><td>${e(t)}</td>${years.map(r=>`<td><input data-history-year="${r.year}" data-history-key="${k}" type="number" step="any" value="${r.values[k]==null?'':r.values[k]/1e8}" aria-label="${r.year}年${e(t)}"></td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function deepDiagnosticView(d){const pct=x=>x==null?'缺项':number(x*100,2)+'%',amt=x=>x==null?'缺项':money(x),days=x=>x==null?'缺项':number(x,1)+'天';let out=`<section class="card"><h2>盈利结构与动态归因</h2><p>比较利润变化来自利润率、资产效率还是杠杆，避免把加债带来的回报提升误认为经营改善。</p>${marketTable(['年度','收入','净利润','毛利率','净利率'],d.profit_trend.map(x=>[x.year,amt(x.revenue),amt(x.net_profit),pct(x.gross_margin),pct(x.net_margin)]))}`;
 out+=diagnosticInsights(d,'profit')+methodNote(d,['structure','shapley','history'],'盈利诊断依据');const a=d.roe_attribution;if(a){const lead=[...a.contributions].sort((x,y)=>Math.abs(y.value)-Math.abs(x.value))[0];out+=`<p class="diagnosis-evidence">${a.from_year}—${a.to_year}年，期末权益回报率变化${number(a.change*100,2)}个百分点，影响最大的代数分项是${e(lead.label)}（${number(lead.value*100,2)}个百分点）。经营效率改善可支持现金回收；杠杆提高不能直接增加可借额度。</p>${marketTable(['分解因素','对回报率变化的贡献'],a.contributions.map(x=>[x.label,number(x.value*100,2)+'个百分点']))}<p class="subtle-caption">${e(a.basis)}</p>`;}else out+=notice('连续两年收入、净利润、资产或权益不齐，或权益非正：暂停动态杜邦归因。');
 if(d.expense_bridge){const b=d.expense_bridge;out+=`<details><summary>利润金额变化桥 · 收入、成本与费用</summary>${marketTable(['来源','利润变化贡献'],b.components.map(x=>[state.boot.labels[x.key]||x.key,money(x.value)]).concat([['其他损益及未拆分项目',money(b.residual)]]))}<p>剩余项包括其他收益、减值、投资损益及营业外项目，不把它强行解释为经营效率。</p></details>`;}else out+='<p class="subtle-caption">成本、期间费用或税费不齐，暂不拆解利润金额变化。</p>';
 out+=`</section><section class="card"><h2>营运资金与现金流分析</h2><p>看收入被应收和库存占用了多少，以及供应商和客户预付款提供了多少支持。天数变长未必异常，需结合行业与账期。</p>${marketTable(['年度','经营性净营运资本','应收天数','存货天数','应付天数','现金周转周期'],d.working_capital.map(x=>[x.year,amt(x.nwc),days(x.receivable_days),days(x.inventory_days),days(x.payable_days),days(x.cash_cycle_days)]))}<p class="subtle-caption">天数统一采用期末余额代理，与上方采用平均余额的指标口径分开。</p>`;
 out+=diagnosticInsights(d,'working');for(const b of d.working_bridges)out+=`<details><summary>${b.year}年资金占用${b.nwc_change>=0?'增加':'释放'}${money(Math.abs(b.nwc_change))}</summary>${marketTable(['科目变化','占用增加为正 / 释放为负'],b.components.map(x=>[state.boot.labels[x.key]||x.key,money(x.change)]))}<p>变动前现金代理${money(b.pre_wc_cash_proxy)}，用于现金情景；余额变化不能完全替代现金流量表附注中的经营调整。</p></details>`;
 out+=`<details><summary>现金流量表勾稽检查</summary>${marketTable(['年度','经营净现金','投资净现金','筹资净现金','期初＋三类现金＋汇率－期末'],d.cash_reconciliation.map(x=>[x.year,amt(x.operating),amt(x.investing),amt(x.financing),amt(x.reconciliation)]))}<p>最后一列应接近零；缺项时不强行补齐。非零请核对报表口径、重述和取数。</p></details>`;
 if(d.support)out+=diagnosticScenarioTable(d)+`<div class="diagnosis-action"><p>用于后续模型：基准年度经营净现金${money(d.support.financing_base_ocf??d.support.base_ocf)}；利润与周转等诊断的保守情景${money(d.support.financing_conservative_ocf??d.support.conservative_ocf)}。融资优化使用两者与用户压力假设中更严格的预计可用于偿债的现金约束，风险模块继续检验同一组合。</p></div><details><summary>现金测算公式与边界</summary><p>${e(d.support.formula)}</p><p>${e(d.support.limitations)}</p></details>`;else out+=notice('连续年度营运资本或现金数据不齐：不启用历史结构现金情景。后续使用现有现金口径并标明假设。','amber');
 out+=improvementTable(d)+methodNote(d,['working','cash'],'营运资金与现金分析依据');return out+`<details><summary>方法依据与分析限制</summary>${d.limitations.map(x=>`<p>${e(x)}</p>`).join('')}<p>上述研究支持分析框架，不为本系统的具体利率、额度和安全线背书；本次未训练预测模型。</p></details></section>`;}
function bindPublic(){
 bindParameterTemplate();
 document.querySelector('#expand-dialogue')?.addEventListener('click',()=>{state.dialogueExpanded=!state.dialogueExpanded;render();requestAnimationFrame(()=>{document.querySelector('#expand-dialogue')?.focus({preventScroll:true});scrollConversation();});});
 document.querySelector('#decision-chat-form')?.addEventListener('submit',ev=>{ev.preventDefault();sendDecisionMessage(ev.currentTarget.elements.message.value);});document.querySelector('#finance-chat-input')?.addEventListener('input',ev=>state.decisionChatDraft=ev.target.value);
 document.querySelectorAll('[data-finance-question]').forEach(el=>el.addEventListener('click',()=>sendDecisionMessage(el.dataset.financeQuestion)));document.querySelectorAll('[data-confirm-proposal]').forEach(el=>el.addEventListener('click',()=>confirmDecisionProposal(el.dataset.confirmProposal,el.dataset.confirmed==='true')));document.querySelector('[data-chat-head]')?.addEventListener('click',async ev=>{await loadRun(ev.currentTarget.dataset.chatHead);render();});loadDecisionChat();
 document.querySelector('#public-task-form')?.addEventListener('submit',async ev=>{ev.preventDefault();const f=ev.currentTarget,d=new FormData(f),b=f.querySelector('button[type=submit]');b.disabled=true;try{const p={...readPublicAssumptions(f),...readPublicRequest(f),objective:'基于已确认融资金额与计算参数，分析下一年度生产经营周转融资及风险。',analysis_mode:'public-v2'};const r=await api('/api/runs',{method:'POST',body:{goal:'融资组合',profile:p,use_ai:d.get('use_ai')==='on'}});await refreshBoot();await loadRun(r.id,true);navigate('execution');}catch(err){document.querySelector('#public-task-error').textContent=err.message;}finally{b.disabled=false;}});
 document.querySelector('#public-company-form')?.addEventListener('submit',async ev=>{ev.preventDefault();const f=ev.currentTarget,d={...structuredClone(state.boot.data),statement_schema:'public-v2',public_provenance:state.boot.data.public_provenance||{}};f.querySelectorAll('[data-meta]').forEach(x=>d[x.dataset.meta]=x.value);f.querySelectorAll('[data-public-field]').forEach(x=>d[x.dataset.publicField]=x.value===''?null:Math.round(Number(x.value)*1e8*100)/100);if(d.financial_history?.length){f.querySelectorAll('[data-history-year]').forEach(x=>{d.financial_history.find(r=>r.year===Number(x.dataset.historyYear)).values[x.dataset.historyKey]=x.value===''?null:Math.round(Number(x.value)*1e8*100)/100;});const latest=d.financial_history.at(-1);for(const rows of Object.values(state.boot.public_blocks))for(const [k,,prior] of rows){latest.values[k]=d[k]??null;const previous=d.financial_history.find(r=>r.year===latest.year-1);if(prior)d[prior]=previous?.values[k]??null;}d.report_period=latest.year+'年度';}try{state.boot=await api('/api/company',{method:'POST',body:{data:d,profile:state.boot.profile,source:'用户录入财报原值'}});if(!state.boot.active_run_id){state.run=null;state.runId=null;state.decisionChat=null;state.decisionChatFor=null;state.decisionChatDraft='';sessionStorage.removeItem('finbridge_run');}navigate('workspace');toast('财报已保存，请确认融资需求。');}catch(err){document.querySelector('#public-company-error').textContent=err.message;}});
}

function scenarioCards(m){let out='';if(m.capacity_result?.available){const c=m.capacity_result;out+=`<div class="scenario-card"><strong>融资能力边界 · 临时测算</strong>${marketTable(['期限','可用净资金','验证'],c.cases.map(x=>[x.months+'个月',x.verified?money(x.net_capacity):'未取得有效结果',x.verified?'通过':'未通过']))}${c.primary?.verified?`${marketTable(['融资渠道','本金','假设年利率'],c.primary.composition.map(x=>[x.name,money(x.amount),valueFmt(x.rate,'%')]))}<p><strong>限制原因：</strong>${e(c.primary.limiting_factors.join('；'))}。${c.primary.stress_coverage!=null?'最紧情景覆盖'+number(c.primary.stress_coverage,2)+'倍。':''}</p><button class="btn small" data-finance-question="采用刚才测算的融资上限，先让我确认" ${state.decisionChatBusy?'disabled':''}>按此上限准备调整</button>`:''}<small>保持当前安全约束；不等于银行授信，也不代表应当借满。正式报告未改变。</small></div>`;}for(const s of m.scenario_previews||[]){out+=`<div class="scenario-card"><strong>临时情景 · ${e(s.id.slice(0,6))}</strong><p>${e('已完成财务分析、融资求解和风险验证，正式报告未改变。')}</p>${s.parameter_items?.length?marketTable(['本轮变更','原值','临时值'],s.parameter_items.map(x=>[x.label,scenarioParameterValue(x.before,x.unit),scenarioParameterValue(x.after,x.unit)])):''}${s.result?.snapshot?.composition?marketTable(['临时渠道','本金','年利率'],s.result.snapshot.composition.map(x=>[x.name,money(x.amount),valueFmt(x.rate,'%')])):''}${marketTable(['比较项目','原方案','临时方案'],(s.result?.comparison||[]).map(x=>[x.label,x.before,x.after]))}${s.financial_change?'<small>财务原值假设，仅作敏感性比较，不写入真实财报。</small>':`<button class="btn small" data-finance-question="采用临时情景 ${e(s.id)}" ${state.decisionChatBusy?'disabled':''}>采用此情景</button>`}</div>`;}return out;}

// Normal layout grows with its contents; the expanded panel scrolls as a whole.
function updateDialogueHeight(){document.querySelector('#decision-chat')?.style.removeProperty('height');}
addEventListener('resize',updateDialogueHeight);

function scenarioParameterValue(v,unit){if(v==null)return '未单独设定';return unit==='money'?money(v):unit==='percent'?number(v*100,2)+'%':number(v,2)+(unit==='days'?'天':unit==='multiple'?'倍':'');}


function decisionConclusion(p){const d=p.decision_summary||{},blocks=d.blockers||[];return `<section class="decision-lead"><h2>${e(d.title||p.status)}</h2>${blocks.length?blocks.map(x=>`<article class="decision-blocker"><h3>${e(x.title)}</h3><p>${e(x.evidence)}</p><p><strong>先处理：</strong>${e(x.action)}</p></article>`).join(''):`<p>${e(d.text||p.status)}</p>`}</section>`;}
function productScreening(p){const rows=p.composition.filter(c=>c.id!=='leasing'),blocked=!!p.decision_summary?.blockers?.length;
 return `<section class="card"><h2>融资渠道如何筛选</h2><p>${blocked?'渠道有测算容量，也必须通过共同的偿债与现金留存检查；本次限制见顶部结论。':'先按收入或资产测算渠道容量，再结合现金、负债和本次需求确定实际配置。'}</p>${marketTable(['候选渠道','容量计算依据','本次计算容量','本次结果'],rows.map(c=>[c.name,c.basis,money(c.capacity),!c.enabled?(c.exclusion_reason||'本次排除'):blocked?'受顶部约束限制':c.amount>.01?'纳入组合':'未选用：当前成本与风险权衡下未配置']))}<p>这里的容量是进入算法的单渠道上限，已受本次需求和手动额度限制；不能相加作为可借总额，也不是银行授信。</p><details><summary>查看本次利率与费用假设</summary>${marketTable(['渠道','假设年利率','手续费率','固定费用'],rows.map(c=>[c.name,valueFmt(c.rate,'%'),valueFmt(c.fee_rate,'%'),money(c.fixed_fee)]))}<p>利率与费用用于比较组合成本，采用当前任务参数，不是银行报价。可在分析报告的对话参数模板中调整后试算。</p></details><details><summary>公开业务依据与假设</summary><p><a href="https://credit.mot.gov.cn/zhengcefagui/202408/t20240807_4147083.html" target="_blank" rel="noopener">流动资金贷款管理办法</a>：用于日常生产经营周转；一年是本系统主动收紧的范围，不是法规统一最长期限。</p><p><a href="https://wealth2.ccb.com/cn/home/company/gsyw/560037.html" target="_blank" rel="noopener">建设银行应收账款融资</a>：公开业务支持以应收账款作质押；本系统12个月为测算合同假设，实际债权账期和担保覆盖须核实，不默认自动替换债权或续贷。</p><p><a href="https://jrj.wuhan.gov.cn/ynzx_57/xwzx/202609/t20260921_2851618.shtml" target="_blank" rel="noopener">2026年9月LPR公开资料</a>。此为带日期参考，不宣称实时更新。</p><p>资产池融资比例、65%负债率上限、1.2倍安全线均为可调整假设，不冒充统一审批标准。</p></details></section>`;
}

function cvarMeaning(p){const r=p.risk_evaluation,d=r.cvar_details;if(!d)return notice('本次结果缺少CVaR分项，请重新载入分析结果。','amber');
 const gap=d.max_safety_gap,allPassed=r.scenarios.every(s=>s.passed),tail=number(d.tail_weight*100,0),formula=d.rows.map(x=>`${money(x.loss)}×${number(x.tail_share*100,2)}%`).join('＋');
 return `<section class="card cvar-meaning"><h2>企业现金余量下降 · 情景CVaR${number(r.cvar_alpha*100,0)}%</h2><p><strong>${money(r.cvar)}</strong>：在所设情景中，最差${tail}%权重对应的企业偿债后现金余量，较基准平均减少这个金额。它包含企业经营压力，可能大于本次融资额；不是这笔贷款会亏损这么多。</p><p><strong>对本次方案意味着什么：</strong>${allPassed?'本次各情景均无需额外补现金即可达到偿债安全线；上述数值表示余量减少，不表示已经还不上债。':`本次最紧情景达到偿债安全线还需${money(gap)}；这是需要处理的安全线缺口，与CVaR的余量下降含义不同。`}${!p.verification?.passed?' 当前方案未通过全部独立验证，不能据此认定融资可行。':''}</p><h3>这个数是怎么算出来的？</h3><p>基准预计可用于偿债的现金${money(d.base_cash)}，减去已有及新增债务年度本息${money(d.base_service)}，基准偿债后余量为${money(d.base_margin)}。</p>${marketTable(['进入尾部平均的情景','预计可用于偿债的现金','较基准现金减少','较基准本息增加','现金余量下降','尾部平均中的占比'],d.rows.map(x=>[x.label,money(x.annual_cash),money(x.cash_decline),money(x.service_increase),money(x.loss),number(x.tail_share*100,2)+'%']))}<p><strong>本次尾部平均：</strong>${formula} ≈ ${money(r.cvar)}。情景余量下降＝max(0，经营现金减少＋本息增加)；分项为负表示现金增加或本息减少。</p><h3>怎么使用这个结果？</h3><p>本次CVaR为${money(r.cvar)}，表示最差${tail}%情景权重内，偿债后现金余量相对基准平均减少${money(r.cvar)}。</p><ul><li><strong>找出主要压力：</strong>查看上表中现金减少与本息增加的贡献，确定应优先改善回款、经营现金还是融资成本。</li><li><strong>比较调整效果：</strong>对同一企业保持情景、权重和置信水平一致，调整融资方案后重新测算；CVaR越小，较差情景下现金余量平均减少得越少。</li></ul><p>融资优化以“一年融资成本＋${number(r.cvar_weight,2)} × CVaR”权衡成本与现金余量的抗压表现。</p><details><summary>权重、置信水平与优化用途</summary><p>${r.scenarios.length}个情景等权，每个权重${number(100/r.scenarios.length,2)}%；取最差${tail}%总权重，边界情景只取所需部分。${e(d.limitations)}</p><p>默认80%用于少量情景下兼顾最差与次差情景，不是行业统一标准；当前值可调整。第二阶段以${number(r.cvar_weight,2)}为风险权重，将CVaR与一年融资成本共同权衡；它不是额外的通过门槛。企业经营现金变化是同一情景下各融资方案共同面对的压力，可能主导结果，因此组合金额也可能不变。</p></details></section>`;
}
